"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[13264],{81457:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"AutoCannonServer","desc":"Authority for the train-mounted AutoCannon (four barrels, hold to fire).\\nDiscovers placed turrets in workspace.PlacedObjects (PlaceableName attribute),\\nseats the gunner after validation (and ejects anyone it did not seat), steps\\nits own yaw/pitch toward the gunner\'s aim reports at the turn-rate limit, and\\nfires FastCast2 spherecast shells from its own rig math. A proximity fuse and\\na direct hit both give the target full damage (`TrainWeaponDamage.applyDirect`)\\nbefore the splash (`applyBlast`). State is published as attributes on the\\nplaced Model: AimYaw, AimPitch, Ammo, Reloading, ReloadEndsAt, GunnerUserId, plus the\\nHUD contract DisplayName, MagazineSize, ReloadTime (read by the generic TurretGui).\\n\\nWith no gunner for `CannonConfig.AutoLoaderIdleTime` and a Smart Cannon /\\nOrbital Sentinel holder in the party, the turret aims at the nearest visible\\nenemy itself and fires at `FireRate x AutoLoaderRate`, credited to the holder.","realm":["Server"],"source":{"line":20,"path":"src/ServerScriptService/AutoCannonServer.server.luau"}}')}}]);